    result = []
    for char in message:
        if char.isalpha():
            if char.islower():
                result.append(shifted_vowels.get(char, char).upper())
            else:
                result.append(shifted_vowels.get(char, char).lower())
        else:
            result.append(char)
    return ''.join(result)
