        if (x, y, len(path)) in visited:
            continue
        visited.add((x, y, len(path)))

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heapq.heappush(pq, (grid[nx][ny], nx, ny, path + [grid[nx][ny]]))

    return []
